package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen1Test {

    @Test
    public void testIsNumber_NullOrEmpty() {
        assertFalse("Null should return false", NumberUtils.isNumber(null));
        assertFalse("Empty string should return false", NumberUtils.isNumber(""));
    }

    @Test
    public void testIsNumber_Integers() {
        assertTrue("Simple integer", NumberUtils.isNumber("123"));
        assertTrue("Zero", NumberUtils.isNumber("0"));
        assertTrue("Negative integer", NumberUtils.isNumber("-123"));
        assertTrue("Integer with type qualifier f", NumberUtils.isNumber("123f"));
        assertTrue("Integer with type qualifier F", NumberUtils.isNumber("123F"));
        assertTrue("Integer with type qualifier d", NumberUtils.isNumber("123d"));
        assertTrue("Integer with type qualifier D", NumberUtils.isNumber("123D"));
        assertTrue("Integer with type qualifier l", NumberUtils.isNumber("123l"));
        assertTrue("Integer with type qualifier L", NumberUtils.isNumber("123L"));
    }

    @Test
    public void testIsNumber_Decimals() {
        assertTrue("Decimal point", NumberUtils.isNumber("123.45"));
        assertTrue("Trailing decimal point", NumberUtils.isNumber("123."));
        assertTrue("Leading decimal point", NumberUtils.isNumber(".123"));
        assertTrue("Negative decimal", NumberUtils.isNumber("-123.45"));
        assertFalse("Two decimal points", NumberUtils.isNumber("123.45.67"));
        assertFalse("Decimal in exponent", NumberUtils.isNumber("123e1.5"));
    }

    @Test
    public void testIsNumber_ScientificNotation() {
        assertTrue("Scientific notation e", NumberUtils.isNumber("123e10"));
        assertTrue("Scientific notation E", NumberUtils.isNumber("123E10"));
        assertTrue("Scientific notation negative exponent", NumberUtils.isNumber("123e-10"));
        assertTrue("Scientific notation positive exponent", NumberUtils.isNumber("123e+10"));
        assertTrue("Scientific notation with decimal", NumberUtils.isNumber("1.23e10"));
        assertFalse("E without preceding digit", NumberUtils.isNumber("e10"));
        assertFalse("Two E's", NumberUtils.isNumber("123e10e10"));
        assertFalse("E at the end", NumberUtils.isNumber("123e"));
        assertFalse("E with sign but no digit", NumberUtils.isNumber("123e+"));
        assertFalse("E with sign but no digit 2", NumberUtils.isNumber("123e-"));
        assertFalse("L with exponent", NumberUtils.isNumber("123e10L"));
    }

    @Test
    public void testIsNumber_Hexadecimal() {
        assertTrue("Hexadecimal lowercase", NumberUtils.isNumber("0x123"));
        assertTrue("Hexadecimal uppercase", NumberUtils.isNumber("0xABC"));
        assertTrue("Hexadecimal with sign", NumberUtils.isNumber("-0x123"));
        assertTrue("Hexadecimal mixed", NumberUtils.isNumber("0x1a2B"));
        assertFalse("Hexadecimal incomplete", NumberUtils.isNumber("0x"));
        assertFalse("Hexadecimal invalid char", NumberUtils.isNumber("0x12G3"));
        assertFalse("Hexadecimal with decimal", NumberUtils.isNumber("0x12.3"));
    }

    @Test
    public void testIsNumber_InvalidCases() {
        assertFalse("Alphabetic string", NumberUtils.isNumber("abc"));
        assertFalse("Just a sign", NumberUtils.isNumber("-"));
        assertFalse("Just a dot", NumberUtils.isNumber("."));
        assertFalse("Dot with sign", NumberUtils.isNumber("-."));
        assertFalse("Space in string", NumberUtils.isNumber("12 3"));
        assertFalse("Special characters", NumberUtils.isNumber("!@#$"));
        assertFalse("Multiple signs", NumberUtils.isNumber("12--3"));
        assertFalse("Sign in wrong place", NumberUtils.isNumber("12-3"));
        assertFalse("Trailing L with exponent", NumberUtils.isNumber("1e1L"));
    }

    @Test
    public void testIsNumber_EdgeCases() {
        // Testing the (i < sz + 1 && allowSigns && !foundDigit) logic
        // This covers cases where a sign follows an E but no digits have been found yet
        assertFalse("Sign after E but no digits", NumberUtils.isNumber("1E-"));

        // Testing the end of loop logic for type qualifiers
        assertTrue("Decimal with L", NumberUtils.isNumber("1.23L"));
        assertFalse("Decimal with L and E", NumberUtils.isNumber("1.23e1L"));

        // Testing trailing decimal point with digit requirement
        assertTrue("Trailing dot valid", NumberUtils.isNumber("1."));
        assertFalse("Trailing dot invalid (no digit)", NumberUtils.isNumber("."));

        // Testing sign at start logic
        assertTrue("Zero with sign", NumberUtils.isNumber("-0"));
    }
}
